mkitem!{mktrait!{# [doc = " This trait is implemented for every type that can be visited,"] # [doc = " providing the skeleton of the traversal."] # [doc = ""] # [doc = " To implement this conveniently, use the derive macro located in"] # [doc = " `rustc_macros`."] pub trait TypeVisitable < I : Interner > : fmt :: Debug { # [doc = " The entry point for visiting. To visit a value `t` with a visitor `v`"] # [doc = " call: `t.visit_with(v)`."] # [doc = ""] # [doc = " For most types, this just traverses the value, calling `visit_with` on"] # [doc = " each field/element."] # [doc = ""] # [doc = " For types of interest (such as `Ty`), the implementation of this method"] # [doc = " that calls a visitor method specifically for that type (such as"] # [doc = " `V::visit_ty`). This is where control transfers from `TypeVisitable` to"] # [doc = " `TypeVisitor`."] fn visit_with < V : TypeVisitor < I > > (& self , visitor : & mut V) -> V :: Result ; }}}
mkitem!{mktrait!{pub trait TypeSuperVisitable < I : Interner > : TypeVisitable < I > { # [doc = " Provides a default visit for a recursive type of interest. This should"] # [doc = " only be called within `TypeVisitor` methods, when a non-custom"] # [doc = " traversal is desired for the value of the type of interest passed to"] # [doc = " that method. For example, in `MyVisitor::visit_ty(ty)`, it is valid to"] # [doc = " call `ty.super_visit_with(self)`, but any other visiting should be done"] # [doc = " with `xyz.visit_with(self)`."] fn super_visit_with < V : TypeVisitor < I > > (& self , visitor : & mut V) -> V :: Result ; }}}
mkitem!{mktrait!{# [doc = " This trait is implemented for every visiting traversal. There is a visit"] # [doc = " method defined for every type of interest. Each such method has a default"] # [doc = " that recurses into the type's fields in a non-custom fashion."] pub trait TypeVisitor < I : Interner > : Sized { # [cfg (feature = "nightly")] type Result : VisitorResult = () ; # [cfg (not (feature = "nightly"))] type Result : VisitorResult ; fn visit_binder < T : TypeVisitable < I > > (& mut self , t : & ty :: Binder < I , T >) -> Self :: Result { t . super_visit_with (self) } fn visit_ty (& mut self , t : I :: Ty) -> Self :: Result { t . super_visit_with (self) } fn visit_region (& mut self , r : I :: Region) -> Self :: Result { if let ty :: ReError (guar) = r . kind () { self . visit_error (guar) } else { Self :: Result :: output () } } fn visit_const (& mut self , c : I :: Const) -> Self :: Result { c . super_visit_with (self) } fn visit_predicate (& mut self , p : I :: Predicate) -> Self :: Result { p . super_visit_with (self) } fn visit_clauses (& mut self , c : I :: Clauses) -> Self :: Result { c . super_visit_with (self) } fn visit_error (& mut self , _guar : I :: ErrorGuaranteed) -> Self :: Result { Self :: Result :: output () } }}}
mkitem!{mkimpl!{impl < I : Interner , T : TypeVisitable < I > , U : TypeVisitable < I > > TypeVisitable < I > for (T , U) { fn visit_with < V : TypeVisitor < I > > (& self , visitor : & mut V) -> V :: Result { try_visit ! (self . 0 . visit_with (visitor)) ; self . 1 . visit_with (visitor) } }}}
mkitem!{mkimpl!{impl < I : Interner , A : TypeVisitable < I > , B : TypeVisitable < I > , C : TypeVisitable < I > > TypeVisitable < I > for (A , B , C) { fn visit_with < V : TypeVisitor < I > > (& self , visitor : & mut V) -> V :: Result { try_visit ! (self . 0 . visit_with (visitor)) ; try_visit ! (self . 1 . visit_with (visitor)) ; self . 2 . visit_with (visitor) } }}}
mkitem!{mkimpl!{impl < I : Interner , T : TypeVisitable < I > > TypeVisitable < I > for Option < T > { fn visit_with < V : TypeVisitor < I > > (& self , visitor : & mut V) -> V :: Result { match self { Some (v) => v . visit_with (visitor) , None => V :: Result :: output () , } } }}}
