mkitem!{mktrait!{pub trait TypeVisitableExt < I : Interner > : TypeVisitable < I > { fn has_type_flags (& self , flags : TypeFlags) -> bool ; # [doc = " Returns `true` if `self` has any late-bound regions that are either"] # [doc = " bound by `binder` or bound by some binder outside of `binder`."] # [doc = " If `binder` is `ty::INNERMOST`, this indicates whether"] # [doc = " there are any late-bound regions that appear free."] fn has_vars_bound_at_or_above (& self , binder : ty :: DebruijnIndex) -> bool ; # [doc = " Returns `true` if this type has any regions that escape `binder` (and"] # [doc = " hence are not bound by it)."] fn has_vars_bound_above (& self , binder : ty :: DebruijnIndex) -> bool { self . has_vars_bound_at_or_above (binder . shifted_in (1)) } # [doc = " Return `true` if this type has regions that are not a part of the type."] # [doc = " For example, `for<'a> fn(&'a i32)` return `false`, while `fn(&'a i32)`"] # [doc = " would return `true`. The latter can occur when traversing through the"] # [doc = " former."] # [doc = ""] # [doc = " See [`HasEscapingVarsVisitor`] for more information."] fn has_escaping_bound_vars (& self) -> bool { self . has_vars_bound_at_or_above (ty :: INNERMOST) } fn has_aliases (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_ALIAS) } fn has_opaque_types (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_TY_OPAQUE) } fn has_coroutines (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_TY_CORO) } fn references_error (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_ERROR) } fn error_reported (& self) -> Result < () , I :: ErrorGuaranteed > ; fn has_non_region_param (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_PARAM - TypeFlags :: HAS_RE_PARAM) } fn has_infer_regions (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_RE_INFER) } fn has_infer_types (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_TY_INFER) } fn has_non_region_infer (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_INFER - TypeFlags :: HAS_RE_INFER) } fn has_infer (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_INFER) } fn has_placeholders (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_PLACEHOLDER) } fn has_non_region_placeholders (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_PLACEHOLDER - TypeFlags :: HAS_RE_PLACEHOLDER) } fn has_param (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_PARAM) } # [doc = " \"Free\" regions in this context means that it has any region"] # [doc = " that is not (a) erased or (b) late-bound."] fn has_free_regions (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_FREE_REGIONS) } fn has_erased_regions (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_RE_ERASED) } # [doc = " True if there are any un-erased free regions."] fn has_erasable_regions (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_FREE_REGIONS) } # [doc = " Indicates whether this value references only 'global'"] # [doc = " generic parameters that are the same regardless of what fn we are"] # [doc = " in. This is used for caching."] fn is_global (& self) -> bool { ! self . has_type_flags (TypeFlags :: HAS_FREE_LOCAL_NAMES) } # [doc = " True if there are any late-bound regions"] fn has_bound_regions (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_RE_BOUND) } # [doc = " True if there are any late-bound non-region variables"] fn has_non_region_bound_vars (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_BOUND_VARS - TypeFlags :: HAS_RE_BOUND) } # [doc = " True if there are any bound variables"] fn has_bound_vars (& self) -> bool { self . has_type_flags (TypeFlags :: HAS_BOUND_VARS) } # [doc = " Indicates whether this value still has parameters/placeholders/inference variables"] # [doc = " which could be replaced later, in a way that would change the results of `impl`"] # [doc = " specialization."] fn still_further_specializable (& self) -> bool { self . has_type_flags (TypeFlags :: STILL_FURTHER_SPECIALIZABLE) } }}}
mkitem!{mkimpl!{impl < I : Interner , T : TypeVisitable < I > > TypeVisitableExt < I > for T { fn has_type_flags (& self , flags : TypeFlags) -> bool { let res = self . visit_with (& mut HasTypeFlagsVisitor { flags }) == ControlFlow :: Break (FoundFlags) ; res } fn has_vars_bound_at_or_above (& self , binder : ty :: DebruijnIndex) -> bool { self . visit_with (& mut HasEscapingVarsVisitor { outer_index : binder }) . is_break () } fn error_reported (& self) -> Result < () , I :: ErrorGuaranteed > { if self . references_error () { if let ControlFlow :: Break (guar) = self . visit_with (& mut HasErrorVisitor) { Err (guar) } else { panic ! ("type flags said there was an error, but now there is not") } } else { Ok (()) } } }}}
mkitem!{mkstruct!{# [derive (Debug , PartialEq , Eq , Copy , Clone)] struct FoundFlags ;}}
mkitem!{mkstruct!{struct HasTypeFlagsVisitor { flags : ty :: TypeFlags , }}}
mkitem!{mkimpl!{impl std :: fmt :: Debug for HasTypeFlagsVisitor { fn fmt (& self , fmt : & mut std :: fmt :: Formatter < '_ >) -> std :: fmt :: Result { self . flags . fmt (fmt) } }}}
mkitem!{mkimpl!{impl < I : Interner > TypeVisitor < I > for HasTypeFlagsVisitor { type Result = ControlFlow < FoundFlags > ; fn visit_binder < T : TypeVisitable < I > > (& mut self , t : & ty :: Binder < I , T >) -> Self :: Result { if self . flags . intersects (TypeFlags :: HAS_BINDER_VARS) && ! t . bound_vars () . is_empty () { return ControlFlow :: Break (FoundFlags) ; } t . super_visit_with (self) } # [inline] fn visit_ty (& mut self , t : I :: Ty) -> Self :: Result { let flags = t . flags () ; if flags . intersects (self . flags) { ControlFlow :: Break (FoundFlags) } else { ControlFlow :: Continue (()) } } # [inline] fn visit_region (& mut self , r : I :: Region) -> Self :: Result { let flags = r . flags () ; if flags . intersects (self . flags) { ControlFlow :: Break (FoundFlags) } else { ControlFlow :: Continue (()) } } # [inline] fn visit_const (& mut self , c : I :: Const) -> Self :: Result { if c . flags () . intersects (self . flags) { ControlFlow :: Break (FoundFlags) } else { ControlFlow :: Continue (()) } } # [inline] fn visit_predicate (& mut self , predicate : I :: Predicate) -> Self :: Result { if predicate . flags () . intersects (self . flags) { ControlFlow :: Break (FoundFlags) } else { ControlFlow :: Continue (()) } } # [inline] fn visit_clauses (& mut self , clauses : I :: Clauses) -> Self :: Result { if clauses . flags () . intersects (self . flags) { ControlFlow :: Break (FoundFlags) } else { ControlFlow :: Continue (()) } } # [inline] fn visit_error (& mut self , _guar : < I as Interner > :: ErrorGuaranteed) -> Self :: Result { if self . flags . intersects (TypeFlags :: HAS_ERROR) { ControlFlow :: Break (FoundFlags) } else { ControlFlow :: Continue (()) } } }}}
mkitem!{mkstruct!{# [derive (Debug , PartialEq , Eq , Copy , Clone)] struct FoundEscapingVars ;}}
mkitem!{mkstruct!{# [doc = " An \"escaping var\" is a bound var whose binder is not part of `t`. A bound var can be a"] # [doc = " bound region or a bound type."] # [doc = ""] # [doc = " So, for example, consider a type like the following, which has two binders:"] # [doc = ""] # [doc = "    for<'a> fn(x: for<'b> fn(&'a isize, &'b isize))"] # [doc = "    ^~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ outer scope"] # [doc = "                  ^~~~~~~~~~~~~~~~~~~~~~~~~~~~  inner scope"] # [doc = ""] # [doc = " This type has *bound regions* (`'a`, `'b`), but it does not have escaping regions, because the"] # [doc = " binders of both `'a` and `'b` are part of the type itself. However, if we consider the *inner"] # [doc = " fn type*, that type has an escaping region: `'a`."] # [doc = ""] # [doc = " Note that what I'm calling an \"escaping var\" is often just called a \"free var\". However,"] # [doc = " we already use the term \"free var\". It refers to the regions or types that we use to represent"] # [doc = " bound regions or type params on a fn definition while we are type checking its body."] # [doc = ""] # [doc = " To clarify, conceptually there is no particular difference between"] # [doc = " an \"escaping\" var and a \"free\" var. However, there is a big"] # [doc = " difference in practice. Basically, when \"entering\" a binding"] # [doc = " level, one is generally required to do some sort of processing to"] # [doc = " a bound var, such as replacing it with a fresh/placeholder"] # [doc = " var, or making an entry in the environment to represent the"] # [doc = " scope to which it is attached, etc. An escaping var represents"] # [doc = " a bound var for which this processing has not yet been done."] struct HasEscapingVarsVisitor { # [doc = " Anything bound by `outer_index` or \"above\" is escaping."] outer_index : ty :: DebruijnIndex , }}}
mkitem!{mkimpl!{impl < I : Interner > TypeVisitor < I > for HasEscapingVarsVisitor { type Result = ControlFlow < FoundEscapingVars > ; fn visit_binder < T : TypeVisitable < I > > (& mut self , t : & ty :: Binder < I , T >) -> Self :: Result { self . outer_index . shift_in (1) ; let result = t . super_visit_with (self) ; self . outer_index . shift_out (1) ; result } # [inline] fn visit_ty (& mut self , t : I :: Ty) -> Self :: Result { if t . outer_exclusive_binder () > self . outer_index { ControlFlow :: Break (FoundEscapingVars) } else { ControlFlow :: Continue (()) } } # [inline] fn visit_region (& mut self , r : I :: Region) -> Self :: Result { if r . outer_exclusive_binder () > self . outer_index { ControlFlow :: Break (FoundEscapingVars) } else { ControlFlow :: Continue (()) } } fn visit_const (& mut self , ct : I :: Const) -> Self :: Result { if ct . outer_exclusive_binder () > self . outer_index { ControlFlow :: Break (FoundEscapingVars) } else { ControlFlow :: Continue (()) } } # [inline] fn visit_predicate (& mut self , predicate : I :: Predicate) -> Self :: Result { if predicate . outer_exclusive_binder () > self . outer_index { ControlFlow :: Break (FoundEscapingVars) } else { ControlFlow :: Continue (()) } } # [inline] fn visit_clauses (& mut self , clauses : I :: Clauses) -> Self :: Result { if clauses . outer_exclusive_binder () > self . outer_index { ControlFlow :: Break (FoundEscapingVars) } else { ControlFlow :: Continue (()) } } }}}
mkitem!{mkstruct!{struct HasErrorVisitor ;}}
mkitem!{mkimpl!{impl < I : Interner > TypeVisitor < I > for HasErrorVisitor { type Result = ControlFlow < I :: ErrorGuaranteed > ; fn visit_error (& mut self , guar : < I as Interner > :: ErrorGuaranteed) -> Self :: Result { ControlFlow :: Break (guar) } }}}